from lib import *
S = SS('s7')
steps = [
    step("response.encoding 的判断顺序(源码 TextResponse._declared_encoding):构造参数 > BOM > HTTP 头 charset > 正文里的 <meta> > 自动探测。同一段 GBK 的中文,头写 gbk 或只有 <meta charset=gbk> 都能还原(encoding=gb18030);头写 utf-8、<meta> 写 gbk 时头赢,结果 14 个替换字符;头写 gbk、<meta> 写 utf-8、正文真的是 utf-8 时头也赢,1 个替换字符;有 BOM 时 BOM 压过头;构造时显式传 encoding=gbk 压过一切。没有头也没有 <meta> 时:GBK 正文被判成 cp949,结果乱码;utf-8 正文判对。", t=tl(S(1)), mark=lidx(S(1), '头 charset=utf-8 + <meta', '头 charset=gbk + <meta', 'BOM', '正文 gbk(自动探测)'), done=lidx(S(1), '头 charset=gbk,正文 gbk', '没有头,<meta', '构造参数', '正文 utf-8(自动探测)'), kv=KV([['顺序', '构造参数 > BOM > 头 > <meta> > 自动探测'], ['头与 <meta> 冲突', '头赢'], ['无头无 meta 的 GBK', '被判成 cp949,乱码']], ['顺序'])),
    step("自动探测靠不住,文本越短越容易错:GBK 3 个字和 6 个字都被判成 cp949,解码结果不一致(★);12 个字以上才判成 gb18030;EUC-KR 3 个字被判成 big5hkscs(★);Big5 一直判成 big5hkscs、Shift_JIS 判成 cp932,这几个解码结果都对。探测逻辑(_auto_detect_fun)先试 ascii、utf-8,都不行才交给 charset-normalizer。", t=tl(S(2)), mark=lidx(S(2), 'gbk  ', 'euc-kr'), done=lidx(S(2), 'big5  ', 'shift_jis'), kv=KV([['GBK 3、6 字', 'cp949★'], ['GBK ≥ 12 字', 'gb18030'], ['EUC-KR 3 字', 'big5hkscs★'], ['Big5 / Shift_JIS', '判对']], ['GBK 3、6 字'])),
    step("声明的编码不对时 Scrapy 不报错:头写 utf-8、正文是 GBK 的 JSON,r.text 里是 12 个替换字符,r.json() 返回 {'����': 3}——两个键解码成同一串替换字符,后一个覆盖前一个,数据已经丢了;没有 charset 的 application/json,GBK 正文被判成 cp949,json() 返回另一种乱码 {'츰俚': '탔녔', '鑒좆': 3};构造时指定 encoding='gbk' 才能得到 {'名字': '爬虫', '数量': 3}。", t=tl(S(3)), mark=lidx(S(3), "r.json() = {'����': 3}", "r2.json()"), done=lidx(S(3), 'r3.json()'), kv=KV([['错误的 utf-8 声明', '不抛异常,满是 \\ufffd'], ['两个键', '解码成同一串,覆盖,丢数据'], ['无 charset 的 JSON', '判成 cp949,另一种乱码']], ['两个键'])),
    step("charset 名字会被规范化(w3lib.resolve_encoding):utf8 → utf-8,gb2312、GBK → gb18030,shift_jis → cp932,euc-kr → cp949,big5 → big5hkscs;latin1、iso-8859-1、ascii、windows-1252 都变成 cp1252(遵循 WHATWG 的编码标准);不认识的 x-unknown 也回落到 cp1252。", t=tl(S(4)), mark=lidx(S(4), 'gb2312', 'latin1', 'ascii', 'x-unknown'), done=lidx(S(4), 'utf8', 'shift_jis', 'euc-kr', 'big5'), kv=KV([['gb2312 / GBK', 'gb18030'], ['latin1 / iso-8859-1 / ascii', 'cp1252'], ['shift_jis / euc-kr / big5', 'cp932 / cp949 / big5hkscs'], ['未知名字', 'cp1252']], ['latin1 / iso-8859-1 / ascii'])),
    step("Content-Type 决定响应类的类型:text/html 与 application/xhtml+xml → HtmlResponse;application/xml、text/xml → XmlResponse;application/json → JsonResponse(2.19 里有这个类);text/plain、application/javascript → TextResponse;image/png、application/octet-stream、application/pdf 和没有 Content-Type(这里 body 是 <a>1</a> 也不会被嗅探)→ 普通 Response,访问 .text 抛 AttributeError: Response content isn't text。", t=tl(S(5)), mark=lidx(S(5), 'image/png', 'octet-stream', 'pdf', '无 Content-Type', 'JsonResponse'), done=lidx(S(5), 'text/html ', 'XmlResponse', 'TextResponse'), kv=KV([['HTML', 'HtmlResponse'], ['XML', 'XmlResponse'], ['JSON', 'JsonResponse'], ['图片 / 二进制 / 无类型', 'Response,没有 .text']], ['图片 / 二进制 / 无类型'])),
    step("真实抓取,服务器发 GBK 正文:头写 charset=gbk → encoding=gb18030,<title> 还原为“爬虫入门”;头没有 charset 但有 <meta charset=gbk> → 同样还原;头错误地写 utf-8(<meta> 是对的)→ 头赢,<title> 是 8 个替换字符;头没有 charset、正文也没有 <meta> → 自动探测成 big5hkscs,<title> 乱码成“鰾單⻌藷”。", t=tl(S(6)), mark=lidx(S(6), '错的', '自动探测'), done=lidx(S(6), '头 charset=gbk ', '头无 charset,<meta'), kv=KV([['头 charset=gbk', '还原'], ['无 charset + <meta>', '还原'], ['头写错', '8 个替换字符'], ['无头无 meta', 'big5hkscs 乱码']], ['头写错'])),
]
A = mkarts('s7', 7, 'Scrapy,Response,编码,charset,TextResponse,真实验证,动画演示',
    '实测 Scrapy 2.19 怎么决定响应编码:构造参数 > BOM > HTTP 头 > <meta> > 自动探测;头写错时不报错但满是替换字符,JSON 的键会因此合并丢数据;短 GBK 文本被自动探测成 cp949;gb2312 → gb18030、latin1 → cp1252;只有文本类型的响应才有 .text。',
    '同一份 GBK 网页,为什么有的能抓对、有的变成乱码?这篇把 Response.encoding 的每一级来源都拿出来冲突一遍,再看自动探测在多短的文本上会出错,以及头里声明错编码后 Scrapy 的表现。',
    [('5 级', 'encoding 的来源顺序:构造参数 > BOM > 头 > <meta> > 自动探测'), ('≥ 12 字', 'GBK 文本自动探测才稳定判成 gb18030(3、6 个字被判成 cp949)'), ('cp1252', 'latin1、iso-8859-1、ascii 以及不认识的名字最终都映射到它')],
    [('判断顺序', '<p><code>TextResponse.encoding</code> 先看构造参数,再依次看 BOM、HTTP 头的 <code>charset</code>、正文里的 <code>&lt;meta&gt;</code>,最后才自动探测。头和 <code>&lt;meta&gt;</code> 冲突时头赢,即使头是错的。</p>'),
     ('自动探测的可靠性', '<p>先试 ascii、utf-8,再交给 charset-normalizer。文本很短时(3、6 个字)GBK 会被判成 cp949,结果乱码;GBK 页面最好让服务器发对头,或在代码里显式指定编码。</p>'),
     ('声明错误的后果', '<p>头里声明错误的编码不会抛异常,<code>.text</code> 里是替换字符;JSON 的键如果全是被替换的字符,会合并成同一个键,数据丢失。</p>'),
     ('编码名规范化', '<p>w3lib 把各种写法映射到 WHATWG 的标准名:gb2312/GBK → gb18030,latin1/ascii → cp1252 等。</p>'),
     ('响应类型', '<p>只有 <code>TextResponse</code> 及其子类(<code>HtmlResponse</code>、<code>XmlResponse</code>、<code>JsonResponse</code>)才有 <code>.text</code> 和选择器;二进制类型是普通 <code>Response</code>。</p>'),
     ('完整抓取', '<p>真实抓取的结果与单元实验一致:头对或 <code>&lt;meta&gt;</code> 对就能还原,头错或什么都没有就乱码。</p>')],
    steps,
    [ENV_Y + '。第一到五节直接在虚拟环境里构造 HtmlResponse / TextResponse(不经网络);第六节用本机服务器发 GBK 字节;编码探测使用 Scrapy 2.19 自带依赖(w3lib 2.5.0、charset-normalizer)',
     '没有验证:真实网站上各编码页面的探测成功率(这里只有四种语言各一小段文字);charset-normalizer 不同版本的差异;HTTP 压缩响应解压后的编码判断;XmlResponse 里 <?xml encoding?> 声明与头冲突时的顺序;请求的 encoding 参数(Request.encoding)对响应的影响'],
    '响应编码')
